 [[[90,-210],[100,-340],[110,-410],[120,-380],[130,-300]],[[60,-180],[70,-350],[80,-470],[90,-420],[100,-310]],[[120,-150],[130,-260],[140,-330],[150,-290],[160,-210]],[[100,-260],[110,-390],[120,-440],[130,-400],[140,-300]]].forEach(rows=>{const text=rows.map(([r,e])=>`${r} pm: ${e}`).join('; '),best=rows.reduce((x,y)=>y[1]<x[1]?y:x),pic={t:'plot',title:'Fictional diatomic: x = distance (pm); y = energy (kJ/mol)',x:[rows[0][0]-10,rows.at(-1)[0]+10],y:[Math.min(...rows.map(r=>r[1]))-60,40],paths:[{pts:rows}]};
  put('energy',`A fictional diatomic molecule has these potential energies in kJ/mol at internuclear distances: ${text}. Part A: what is the bond length, in pm, taking the distance of lowest energy listed?`,best[0],pic,`The bond length is the distance where the potential energy is lowest: ${best[1]} kJ/mol at ${best[0]} pm.`);
  put('energy',`A fictional diatomic molecule has these potential energies in kJ/mol at internuclear distances: ${text}. Part B: what is the bond energy, in kJ/mol, taking the depth of the lowest energy listed below zero?`,-best[1],pic,`The bond energy is the depth of the well below the separated-atoms level of 0: |${best[1]}| = ${-best[1]} kJ/mol.`);});
 [[2,2,200,1,1,200],[1,1,150,1,1,300],[3,2,250,1,1,200]].forEach(([a,b,d1,c,e,d2])=>put('energy',`By Coulomb’s law the attraction energy magnitude is proportional to q₁q₂ ÷ d. Pair 1 has charges +${a} and −${b} at ${d1} pm; Pair 2 has +${c} and −${e} at ${d2} pm. How many times larger is Pair 1’s attraction energy than Pair 2’s? Round to two decimals.`,r2((a*b/d1)/(c*e/d2)),board('Compare q₁q₂ ÷ d',[`Pair 1: ${a} × ${b} ÷ ${d1}`,`Pair 2: ${c} × ${e} ÷ ${d2}`,'ratio = ?']),`Pair 1 is ${a*b}/${d1} and Pair 2 is ${c*e}/${d2}; dividing gives ${r2((a*b/d1)/(c*e/d2))}.`));
 fact('energy',[
  ['On a potential-energy curve for two bonded atoms, what does the lowest point of the curve represent?','the equilibrium bond length, where the pair is most stable','the distance at which the two nuclei touch','the energy of the two atoms infinitely far apart','The curve bottoms out at the bond length, below the zero of separated atoms, because attractions and repulsions balance there.'],
  ['Two atoms are pushed closer together than their equilibrium bond length. Why does the potential energy rise steeply?','repulsion between the nuclei and between the electron clouds grows rapidly','the attraction between the atoms drops to zero at short distance','the atoms lose all of their valence electrons','At short range the repulsions dominate, so squeezing the atoms together costs a large amount of energy.'],
  ['A bond is broken in the gas phase. Which statement about the energy change is correct?','energy must be absorbed, equal to the bond energy','energy is released, equal to the bond energy','there is no net energy change','Breaking a bond requires energy input equal to the bond energy; forming that bond releases the same amount.'],
  ['A student compares the N–N, N=N and N≡N bonds. Which is shortest with the greatest bond energy?','the triple bond, since more shared pairs pull the nuclei closer','the single bond, since it has the fewest shared pairs','the double bond, since it is intermediate in every property','More shared electron pairs give a shorter, stronger bond; typical values are about 145, 125 and 110 pm with energies near 160, 418 and 941 kJ/mol.']]);
