 [['Al³⁺','O²⁻','Al₂O₃',3,2,'cations'],['Ca²⁺','PO₄³⁻','Ca₃(PO₄)₂',2,3,'cations'],['Fe³⁺','SO₄²⁻','Fe₂(SO₄)₃',3,2,'anions']].forEach(([X,Y,F,qa,qb,want],i)=>{const g=(function gcd(a,b){return b?gcd(b,a%b):a;})(qa,qb),nc=qb/g,na=qa/g;
  put('ionic',`A fictional lab combines ${X} and ${Y} ions into one neutral ionic compound written with the simplest whole-number ratio. How many ${want==='cations'?X:Y} ions are in one formula unit?`,want==='cations'?nc:na,board('Balance the charges',[`cation: ${X}`,`anion: ${Y}`,'smallest equal total + and − charge']),`The smallest ratio with zero net charge is ${nc} ${X} to ${na} ${Y}, as in ${F}; the subscript of one ion is the charge size of the other divided by their greatest common factor.`);});
