 [['K','I'],['Sr','O'],['Li','Br']].forEach(([a,b])=>{const q=CHG[a]*CHG[b],cat=`${a}${SUP[CHG[a]]}⁺`,an=`${b}${SUP[CHG[b]]}⁻`;put('ionic',`Use the typical ionic radii ${cat} ${RAD[a]} pm and ${an} ${RAD[b]} pm. Compute the Coulomb index |q⁺q⁻| ÷ (r⁺ + r⁻) × 1000 for one cation paired with one anion as ${a}${b}. Round to two decimals.`,r2(idx(CHG[a],CHG[b],a,b)),board('Index setup',[`charges: ${CHG[a]} × ${CHG[b]} = ${q}`,`distance: ${RAD[a]} + ${RAD[b]} = ${RAD[a]+RAD[b]} pm`,'index = ?']),`The charge product is ${q} and the distance ${RAD[a]+RAD[b]} pm, so the index is ${q} ÷ ${RAD[a]+RAD[b]} × 1000 = ${r2(idx(CHG[a],CHG[b],a,b)).toFixed(2)}.`);});
 [[['Na','Cl'],['K','Cl']],[['Sr','O'],['Ba','O']],[['Li','Br'],['Li','I']],[['K','I'],['Ca','S']]].forEach(([p1,p2],i)=>{const n=p=>p[0]+p[1],v=p=>idx(CHG[p[0]],CHG[p[1]],p[0],p[1]),right=v(p1)>v(p2)?n(p1):n(p2),d=p=>`${n(p)} (+${CHG[p[0]]}, −${CHG[p[1]]}, ${RAD[p[0]]} pm and ${RAD[p[1]]} pm)`,c=choose(right,[right===n(p1)?n(p2):n(p1),'they are equal'],i+1);
  put('ionic',`Using Coulomb’s law with the radii given, which ionic solid has the larger lattice energy: ${d(p1)} or ${d(p2)}? ${c.text}. Answer A, B or C.`,c.letter,board('Compare |q⁺q⁻| ÷ (r⁺ + r⁻)',[`${n(p1)}: ${CHG[p1[0]]*CHG[p1[1]]} ÷ ${RAD[p1[0]]+RAD[p1[1]]}`,`${n(p2)}: ${CHG[p2[0]]*CHG[p2[1]]} ÷ ${RAD[p2[0]]+RAD[p2[1]]}`]),`The larger charge product over the smaller distance wins: ${n(p1)} is ${r2(v(p1))} and ${n(p2)} is ${r2(v(p2))} on the index, so ${right} has the larger lattice energy.`,[right]);});
 fact('ionic',[
  ['Solid sodium chloride shatters when struck sharply. What best explains this brittleness?','shifting a layer lines up like-charged ions, and their repulsion splits the crystal','its ions are free to flow past each other like electrons in a metal','its covalent bonds form long chains that snap in one direction','In an ionic lattice a displaced layer brings like charges together, so repulsion cleaves the crystal instead of letting layers slide.'],
  ['Solid NaCl does not conduct electricity but molten NaCl does. Which reason fits?','the ions are fixed in the solid but able to move when molten','electrons are delocalized only in the liquid','the solid contains no charged particles','Conduction needs mobile charge carriers; the ions are locked in place in the solid and free to move in the liquid or in solution.'],
  ['Which property most directly follows from a very large lattice energy?','a high melting point','a low melting point because the ions are loosely held','good electrical conduction as a solid','A large lattice energy means strong attractions throughout the lattice, so much energy is needed to separate the ions, giving a high melting point.'],
  ['Which statement best describes the structure of solid sodium chloride?','a repeating three-dimensional array of alternating cations and anions','separate NaCl molecules held together by weak forces only','neutral atoms surrounded by a sea of electrons','The solid is an extended lattice in which every ion is attracted to neighbours of opposite charge; the formula shows only the ion ratio.'],
  ['A student calls one NaCl in the solid a molecule. What is the best correction?','NaCl is a formula unit giving the simplest ion ratio of a lattice','NaCl is a molecule because Na and Cl share a pair equally','NaCl is a metal because it contains sodium','An ionic solid has no discrete molecules; the formula unit is the simplest whole-number ratio of ions that makes the lattice neutral.']]);
